#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto t_vec = noarr::vector<'t'>();

// Simple tuning container
struct tuning_t {
	// A: i x j
	// Layout: scalar<num_t>() ^ j_vec ^ i_vec
	//   -> dimensions: 'i' (outer), 'j' (inner, contiguous)
	// This gives row-major storage: for a fixed i, j varies over
	// contiguous memory which is good for the LU row updates.
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);

	// Tunable block size for the j-dimension in the LU kernel.
	// Must be > 0. It does not need to divide N, the traversal
	// uses into_blocks_dynamic to handle the remainder safely.
	static constexpr std::size_t lu_block_j = 64;
};

// Global constexpr instance used to access proto-structures
constexpr tuning_t tuning{};

// 1D helper structures for k- and t-iterations (no actual data, only for traversal)
constexpr auto k_structure = noarr::scalar<char>() ^ k_vec;
constexpr auto t_structure = noarr::scalar<char>() ^ t_vec;

// initialization function
void init_array(auto A) {
	// A: i x j
	using namespace noarr;

	auto n = A | get_length<'i'>(); // matrix is n x n

	// ---------------------------------------------------------------------
	// 1) Initialize A as unit-lower plus some values below diagonal, 0 above
	// ---------------------------------------------------------------------
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const int nn = static_cast<int>(n);
		const int jj = static_cast<int>(j);

		if (j < i) {
			// A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
			num_t val = static_cast<num_t>((-jj % nn));
			val /= static_cast<num_t>(nn);
			val += static_cast<num_t>(1);
			A[state] = val;
		} else if (j == i) {
			A[state] = static_cast<num_t>(1);
		} else { // j > i
			A[state] = static_cast<num_t>(0);
		}
	});

	// ---------------------------------------------------------------------
	// 2) Make the matrix positive semi-definite:
	//    B[r][s] = sum_t A[r][t] * A[s][t];  then A = B
	//
	// Original code:
	//   - zeroed B
	//   - ran t outer, then r,s inner (rank-1 updates)
	//     => each element B[r,s] was revisited n times with poor temporal locality.
	//
	// Optimized version:
	//   - keep B[r,s] in a local accumulator while iterating over t
	//   - write B[r,s] once at the end
	//   - this keeps B[r,s] in registers and improves cache behavior for B
	// ---------------------------------------------------------------------

	auto B = noarr::bag(A.structure()); // same layout as A

	// Pre-build a 1D traverser over t: 0 <= t < n
	auto t_trav = traverser(t_structure ^ set_length<'t'>(n));

	// For each pair (r,s) compute the dot product of row r and row s of A
	traverser(B).for_each([&](auto rs_state) {
		auto [r, s] = get_indices<'i', 'j'>(rs_state);

		// Precompute base states for the two rows; we will combine them
		// with a column-state using state arithmetic.
		auto row_r_state = idx<'i'>(r);
		auto row_s_state = idx<'i'>(s);

		num_t sum = static_cast<num_t>(0);

		t_trav.for_each([&](auto t_state) {
			auto t = get_index<'t'>(t_state);

			// Column index state
			auto col_t_state = idx<'j'>(t);

			// Full (i,j) states are built by adding row and column states.
			// This avoids rebuilding two-index states from scratch each time.
			auto rt_state = row_r_state + col_t_state; // (r, t)
			auto st_state = row_s_state + col_t_state; // (s, t)

			sum += A[rt_state] * A[st_state];
		});

		B[rs_state] = sum;
	});

	// Copy B back into A
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	// A: i x j (n x n)
	using namespace noarr;

	auto n = A | get_length<'i'>();

	// ---------------------------------------------------------------------
	// Pre-build helper traversers / proto-structures used inside the kernel
	// ---------------------------------------------------------------------

	// 1D structure for the k-loop, sized once up-front for the maximum
	// possible length 'n'. Individual loops will restrict it with slice().
	auto k_full_structure = k_structure ^ set_length<'k'>(n);
	auto trav_k_full = traverser(k_full_structure);

	// Proto-structure for blocking the j-dimension.
	// We use into_blocks_dynamic so that n does not need to be a multiple of
	// tuning_t::lu_block_j. The additional "presence" dimension introduced
	// by into_blocks_dynamic is handled internally by the traverser; the
	// states we see still only contain 'i' and 'j'.
	constexpr auto j_blocking =
		noarr::into_blocks_dynamic<'j', 'J', 'j', 'p'>(noarr::lit<tuning_t::lu_block_j>) ^
		noarr::hoist<'J'>();

	// ---------------------------------------------------------------------
	// LU factorization without pivoting.
	//
	// Canonical algorithm:
	//
	// for i = 0..n-1:
	//   // strictly lower triangular part (L)
	//   for j = 0..i-1:
	//     for k = 0..j-1:
	//       A[i][j] -= A[i][k] * A[k][j];
	//     A[i][j] /= A[j][j];
	//
	//   // upper triangular part (U, including diagonal)
	//   for j = i..n-1:
	//     for k = 0..i-1:
	//       A[i][j] -= A[i][k] * A[k][j];
	//
	// The original code implemented the two j-ranges with separate
	// traverser slices. Here we merge them into a single traversal over
	// j, compute the correct k-limit on the fly, and keep the division
	// only for j < i. This reduces traverser construction overhead while
	// preserving the dependency order:
	//   - i is processed in increasing order
	//   - for fixed i, j is processed in increasing order
	// which is required for correctness of the L update.
	//
	// Additionally, we:
	//   - reuse the k-traverser for all inner loops and restrict it
	//     via slice<'k'>(0, k_limit) instead of recreating it
	//   - apply a j-blocking traversal (j_blocking) to improve cache and
	//     SIMD utilisation along the contiguous j-dimension; the logical
	//     order of j remains increasing, so correctness is preserved.
	// ---------------------------------------------------------------------

	#pragma scop
	traverser(A)
		.template for_dims<'i'>([&](auto trav_i_base) {
			// Apply j-blocking to the current row view.
			auto trav_i = trav_i_base.order(j_blocking);

			auto state_i = trav_i.state(); // contains only 'i'
			auto i_idx = get_index<'i'>(state_i);

			// For convenience, build a base state for the fixed row i.
			auto row_i_state = idx<'i'>(i_idx);

			// Traverse all columns j in the (potentially blocked) j-order.
			trav_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state(); // still only 'i' and 'j'
				auto j_idx = get_index<'j'>(state_ij);

				// Base column state for this j.
				auto col_j_state = idx<'j'>(j_idx);

				// State for A(i,j) and a direct reference so that the address
				// computation is performed only once per (i,j).
				auto ij_state = row_i_state + col_j_state;
				num_t &a_ij = A[ij_state];

				// The upper bound of the k-loop depends on whether we are
				// computing the lower (j < i) or upper (j >= i) triangular part:
				//   - j < i: 0 <= k < j
				//   - j >= i: 0 <= k < i
				std::size_t k_limit = (j_idx < i_idx) ? j_idx : i_idx;

				if (k_limit > 0) {
					// Iterate 0 <= k < k_limit using the pre-built 1D traverser.
					trav_k_full
						.order(noarr::slice<'k'>(0, k_limit))
						.for_each([&](auto k_state) {
							auto k_idx = get_index<'k'>(k_state);

							// Build the two required (i,j) states using simple
							// state arithmetic to avoid reconstructing both
							// indices from scratch.
							auto col_k_state = idx<'j'>(k_idx);
							auto row_k_state = idx<'i'>(k_idx);

							auto ik_state = row_i_state + col_k_state; // (i, k)
							auto kj_state = row_k_state + col_j_state; // (k, j)

							a_ij -= A[ik_state] * A[kj_state];
						});
				}

				// For the strictly lower triangular part we additionally divide
				// by the diagonal entry A(j,j) to complete L.
				if (j_idx < i_idx) {
					auto jj_row_state = idx<'i'>(j_idx);
					auto jj_col_state = idx<'j'>(j_idx);
					auto jj_state = jj_row_state + jj_col_state; // (j, j)
					a_ij /= A[jj_state];
				}
			});
		});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// A: n x n
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_lu(A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (and prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
