	using namespace noarr;

	auto n = A | get_length<'i'>(); // matrix is n x n

	// --------------------------------------------------------------------
	// 1) Initialize A as unit-lower plus some values below diagonal, 0 above
	// --------------------------------------------------------------------
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const int nn = static_cast<int>(n);
		const int jj = static_cast<int>(j);

		if (j < i) {
			// A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
			num_t val = static_cast<num_t>((-jj % nn));
			val /= static_cast<num_t>(nn);
			val += static_cast<num_t>(1);
			A[state] = val;
		} else if (j == i) {
			A[state] = static_cast<num_t>(1);
		} else { // j > i
			A[state] = static_cast<num_t>(0);
		}
	});

	// --------------------------------------------------------------------
	// 2) Make the matrix positive semi-definite:
	//
	//    B[r][s] = sum_t A[r][t] * A[s][t];  then A = B
	//
	//    This is B = A * A^T, which is symmetric positive semi-definite.
	//    The original version iterated t outermost and updated every
	//    B[r][s] n times. Here we:
	//      - compute one (r,s) element at a time,
	//      - accumulate the whole dot product in a register,
	//      - exploit symmetry by computing only r <= s and mirroring.
	//
	//    This reduces memory traffic (one write per B[r][s]) and halves
	//    the number of multiplications while preserving the mathematical
	//    result B = A * A^T exactly.
	// --------------------------------------------------------------------
	auto B = noarr::bag(A.structure());

	// Traverser over the "t" (column) dimension, reused for every B[r][s]
	auto t_trav = traverser(t_structure).order(set_length<'t'>(n));

	// Traverse upper triangle of B (r <= s) using i as outer and j as inner
	traverser(B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, 'j' free
		auto state_i = trav_i.state();
		auto r = get_index<'i'>(state_i);

		// For each row r, we only need columns s in [r, n)
		auto len_j = n - r;
		auto trav_upper_row = trav_i.order(slice<'j'>(r, len_j));

		trav_upper_row.template for_dims<'j'>([&](auto trav_rs) {
			// trav_rs has both 'i' and 'j' fixed -> one element B[r][s]
			auto rs_state = trav_rs.state();
			auto s = get_index<'j'>(rs_state);

			// Accumulate B[r][s] = sum_t A[r][t] * A[s][t]
			num_t sum = static_cast<num_t>(0);

			t_trav.for_each([&](auto t_state) {
				auto t = get_index<'t'>(t_state);

				auto rt_state = noarr::idx<'i', 'j'>(r, t);
				auto st_state = noarr::idx<'i', 'j'>(s, t);

				sum += A[rt_state] * A[st_state];
			});

			// Write upper triangle element
			B[rs_state] = sum;

			// Mirror to lower triangle if off-diagonal
			if (s != r) {
				auto sr_state = noarr::idx<'i', 'j'>(s, r);
				B[sr_state] = sum;
			}
		});
	});

	// --------------------------------------------------------------------
	// 3) Copy B back into A
	// --------------------------------------------------------------------
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// computation kernel: in-place LU decomposition without pivoting
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	// A: i x j (n x n)
	using namespace noarr;

	auto n = A | get_length<'i'>();

	// Reusable traverser for the k-dimension [0, n)
	// Individual k-ranges (0..j-1 or 0..i-1) are obtained via .order(slice<'k'>())
	auto k_full_trav = traverser(k_structure).order(set_length<'k'>(n));

	#pragma scop
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, 'j' free
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// ------------------------------------------------------------
		// First inner loop: 0 <= j < i
		//   A[i][j] -= sum_{k=0}^{j-1} A[i][k] * A[k][j];
		//   A[i][j] /= A[j][j];
		//
		// We:
		//   - restrict traversal to j in [0, i),
		//   - use a k-traverser sliced to [0, j),
		//   - accumulate the sum in a local variable for better
		//     register use and vectorization.
		// ------------------------------------------------------------
		if (i_idx > 0) {
			// j in [0, i_idx)
			auto trav_j_lt_i = trav_i.order(noarr::slice<'j'>(0, i_idx));

			trav_j_lt_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				auto j_idx = get_index<'j'>(state_ij);

				auto ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);

				// For j == 0, the sum is empty
				if (j_idx > 0) {
					// k in [0, j_idx)
					auto k_trav = k_full_trav.order(noarr::slice<'k'>(0, j_idx));

					num_t sum = static_cast<num_t>(0);

					k_trav.for_each([&](auto k_state) {
						auto k_idx = get_index<'k'>(k_state);

						auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
						auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

						sum += A[ik_state] * A[kj_state];
					});

					A[ij_state] -= sum;
				}

				// A[i][j] /= A[j][j];
				auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				A[ij_state] /= A[jj_state];
			});
		}

		// ------------------------------------------------------------
		// Second inner loop: i <= j < n
		//   A[i][j] -= sum_{k=0}^{i-1} A[i][k] * A[k][j];
		//
		// Again, we:
		//   - restrict traversal to j in [i, n),
		//   - use k in [0, i), accumulated in a local sum.
		// ------------------------------------------------------------
		auto len_second = n - i_idx; // always >= 1 if n > 0
		auto trav_j_ge_i = trav_i.order(noarr::slice<'j'>(i_idx, len_second));

		trav_j_ge_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state();
			auto j_idx = get_index<'j'>(state_ij);

			auto ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);

			if (i_idx > 0) {
				// k in [0, i_idx)
				auto k_trav = k_full_trav.order(noarr::slice<'k'>(0, i_idx));

				num_t sum = static_cast<num_t>(0);

				k_trav.for_each([&](auto k_state) {
					auto k_idx = get_index<'k'>(k_state);

					auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
					auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

					sum += A[ik_state] * A[kj_state];
				});

				A[ij_state] -= sum;
			}
		});
	});
	#pragma endscop
}

} // namespace

