	// 2) Make the matrix positive semi-definite:
	//    B[r][s] = sum_t A[r][t] * A[s][t];  then A = B
	//
	// Original code had loops ordered as:
	//   for t
	//     for r,s
	//       B[r][s] += A[r][t] * A[s][t];
	//
	// That walks B in a cache-friendly way, but touches each B[r][s]
	// once per t. Here we instead accumulate B[r][s] *locally*:
	//
	//   for r
	//     for s
	//       sum = 0;
	//       for t
	//         sum += A[r][t] * A[s][t];
	//       B[r][s] = sum;
	//
	// This keeps A accesses contiguous along t (row-wise in current
	// layout) and touches each B[r][s] only once, improving locality
	// while preserving mathematical semantics (up to FP roundoff).
	// ------------------------------------------------------------------

	auto B = noarr::bag(A.structure());

