			// trav_rs has both 'i' and 'j' fixed
			auto state_rs = trav_rs.state();
			auto s = get_index<'j'>(state_rs);

			num_t sum = static_cast<num_t>(0);

			// Accumulate the dot product over t
			trav_t.for_each([&](auto t_state) {
				auto t = get_index<'t'>(t_state);

				auto rt_state = noarr::idx<'i', 'j'>(r, t);
				auto st_state = noarr::idx<'i', 'j'>(s, t);

				sum += A[rt_state] * A[st_state];
			});

			B[state_rs] = sum;
		});
	});

	// Copy B back into A
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	// A: i x j (n x n)
	using namespace noarr;

	auto n = A | get_length<'i'>();

	// Static tuning parameter for j-blocking
	constexpr std::size_t J_BLOCK = tuning::j_block;

	#pragma scop
	// Outer loop over i (row index)
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// ------------------------------------------------------------------
		// First inner loop: 0 <= j < i
		//
		// We block this range in the j-dimension using an auxiliary
		// "block index" dimension 'b'. For each block, we restrict the
		// traverser to a slice of j and then iterate j inside the block.
		// Global order of j for a fixed i remains ascending:
		//   j = 0..i-1  (in increasing order),
		// just grouped into contiguous blocks. This preserves the
		// dependence A[i][j] using A[i][k] for k < j.
		// ------------------------------------------------------------------
		if (i_idx > 0) {
			std::size_t len_first = i_idx; // number of j with j < i
			std::size_t num_blocks_first = (len_first + J_BLOCK - 1) / J_BLOCK;

			traverser(b_structure)
				.order(noarr::set_length<'b'>(num_blocks_first))
				.for_each([&](auto b_state) {
					auto b_idx = get_index<'b'>(b_state);

					std::size_t block_start = b_idx * J_BLOCK;
					if (block_start >= len_first)
						return; // safety, should not trigger

					std::size_t remaining = len_first - block_start;
					std::size_t block_len = remaining < J_BLOCK ? remaining : J_BLOCK;

					// Restrict trav_i to j in [block_start, block_start + block_len)
					auto trav_j_block = trav_i.order(noarr::slice<'j'>(block_start, block_len));

					trav_j_block.template for_dims<'j'>([&](auto trav_ij) {
						// trav_ij has 'i' and 'j' fixed
						auto state_ij = trav_ij.state();
						auto j_idx = get_index<'j'>(state_ij);

						auto ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);

						// for (k = 0; k < j; k++)
						if (j_idx > 0) {
							traverser(k_structure)
								.order(noarr::set_length<'k'>(j_idx))
								.for_each([&](auto k_state) {
									auto k_idx = get_index<'k'>(k_state);

									auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
									auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

									A[ij_state] -= A[ik_state] * A[kj_state];
								});
						}

						// A[i][j] /= A[j][j];
						auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
						A[ij_state] /= A[jj_state];
					});
				});
		}

		// ------------------------------------------------------------------
		// Second inner loop: i <= j < n
		//
		// Same j-blocking pattern as above, but now over the range
		// [i_idx, n). Dependencies in this loop do *not* couple
		// different j (each j uses A[i][k] and A[k][j] with k < i),
		// so any reordering of j within this range is valid; we still
		// keep it ascending for simplicity.
		// ------------------------------------------------------------------
		std::size_t len_second = n - i_idx;
		if (len_second > 0) {
			std::size_t num_blocks_second = (len_second + J_BLOCK - 1) / J_BLOCK;

			traverser(b_structure)
				.order(noarr::set_length<'b'>(num_blocks_second))
				.for_each([&](auto b_state) {
					auto b_idx = get_index<'b'>(b_state);

					std::size_t block_start = i_idx + b_idx * J_BLOCK;
					if (block_start >= n)
						return; // safety, should not trigger

					std::size_t remaining = n - block_start;
					std::size_t block_len = remaining < J_BLOCK ? remaining : J_BLOCK;

					// Restrict trav_i to j in [block_start, block_start + block_len)
					auto trav_j_block = trav_i.order(noarr::slice<'j'>(block_start, block_len));

					trav_j_block.template for_dims<'j'>([&](auto trav_ij) {
						// trav_ij has 'i' and 'j' fixed
						auto state_ij = trav_ij.state();
						auto j_idx = get_index<'j'>(state_ij);

						auto ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);

						// for (k = 0; k < i; k++)
						if (i_idx > 0) {
							traverser(k_structure)
								.order(noarr::set_length<'k'>(i_idx))
								.for_each([&](auto k_state) {
									auto k_idx = get_index<'k'>(k_state);

									auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
									auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

									A[ij_state] -= A[ik_state] * A[kj_state];
								});
						}
					});
				});
		}
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// A: n x n
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_lu(A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (and prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
