	// Make the matrix positive semi-definite:
	//   B[r][s] = sum_t A[r][t] * A[s][t];  then A = B
	//
	// Compared to the original code, we change the loop ordering to improve
	// locality and keep the accumulation in a register:
	//
	//   Original:
	//     for t
	//       for r,s
	//         B[r,s] += A[r,t] * A[s,t];
	//
	//   New:
	//     for r,s
	//       acc = 0;
	//       for t
	//         acc += A[r,t] * A[s,t];
	//       B[r,s] = acc;
	//
