	// summation order changes) while reducing memory traffic to B.
	// -------------------------------------------------------------------------
	auto B = noarr::bag(A.structure());

	// Zero B (kept for clarity; the new accumulation overwrites each element)
	traverser(B).for_each([&](auto state) {
		B[state] = static_cast<num_t>(0);
	});

	// Pre-build the t-traverser with the fixed length n.
	auto t_trav = traverser(t_structure).order(set_length<'t'>(n));

	// For every (r, s), compute B[r][s] = sum_t A[r][t] * A[s][t]
	traverser(B).for_each([&](auto rs_state) {
		auto [r, s] = get_indices<'i', 'j'>(rs_state);

		num_t acc = static_cast<num_t>(0);

		t_trav.for_each([&](auto t_state) {
			auto t = get_index<'t'>(t_state);

			auto rt_state = noarr::idx<'i', 'j'>(r, t);
			auto st_state = noarr::idx<'i', 'j'>(s, t);

			acc += A[rt_state] * A[st_state];
		});

		B[rs_state] = acc;
	});

