//
// We keep the classical LU factorization (no pivoting)
//
//   for i = 0..n-1
//     // 1) compute L(i, j) for j < i
//     for j = 0..i-1
//       for k = 0..j-1
//         A[i][j] -= A[i][k] * A[k][j];
//       A[i][j] /= A[j][j];
//
//     // 2) compute U(i, j) for j >= i
//     for j = i..n-1
//       for k = 0..i-1
//         A[i][j] -= A[i][k] * A[k][j];
//
// but we **restructure the second phase** to improve locality:
//
//     for k = 0..i-1
//       aik = A[i][k];
//       for j = i..n-1
//         A[i][j] -= aik * A[k][j];
//
