	auto k_trav_base = traverser(k_structure);

	#pragma scop
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// ---------------------------------------------------------------------
		// 1) Lower part: j < i
		//
		// for (j = 0; j < i; j++) {
		//   for (k = 0; k < j; k++)
		//     A[i][j] -= A[i][k] * A[k][j];
		//   A[i][j] /= A[j][j];
		// }
		// ---------------------------------------------------------------------
		if (i_idx > 0) {
			// Restrict 'j' to [0, i_idx)
			auto trav_j_lt_i = trav_i.order(noarr::slice<'j'>(0, i_idx));

			trav_j_lt_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				auto j_idx = get_index<'j'>(state_ij);

				auto ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);

				// Inner k-loop: 0 <= k < j
				if (j_idx > 0) {
					// Constrain k to [0, j_idx)
					auto k_trav_j = k_trav_base.order(noarr::set_length<'k'>(j_idx));

					k_trav_j.for_each([&](auto k_state) {
						auto k_idx = get_index<'k'>(k_state);

  						auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
						auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

						A[ij_state] -= A[ik_state] * A[kj_state];
					});
				}

				// A[i][j] /= A[j][j];
				auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				A[ij_state] /= A[jj_state];
			});
		}

		// ---------------------------------------------------------------------
		// 2) Upper part: j >= i
		//
		// Original:
		//   for (j = i; j < n; j++)
		//     for (k = 0; k < i; k++)
		//       A[i][j] -= A[i][k] * A[k][j];
		//
		// Optimized (loop reordering):
		//   for (k = 0; k < i; k++) {
		//     aik = A[i][k];
		//     for (j = i; j < n; j++)
		//       A[i][j] -= aik * A[k][j];
		//   }
		//
		// This is algebraically equivalent: the double sum over (k, j) is the
		// same, only the order of updates changes. For each i, the entries
		// A[i][k] with k < i are already finalized by the first phase and are
		// constant during this phase, so there are no write–after–read hazards.
		//
		// We keep 'j' as the innermost dimension to exploit that it is stored
		// contiguously (tuning.a_layout = j_vec ^ i_vec).
		// ---------------------------------------------------------------------
		if (i_idx > 0) {
			auto len_second = n - i_idx;
			if (len_second > 0) {
				// j-range [i_idx, n)
				auto trav_j_tail = trav_i.order(noarr::slice<'j'>(i_idx, len_second));

				// k-range [0, i_idx)
				auto k_trav_i = k_trav_base.order(noarr::set_length<'k'>(i_idx));

				// Outer loop over k
				k_trav_i.for_each([&](auto k_state) {
					auto k_idx = get_index<'k'>(k_state);

					// A[i][k] is reused for all j in the tail; keep it in a register
					auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
					num_t aik = A[ik_state];

