//       This is algebraically equivalent because the sum over k is
//       associative and independent of j.  The benefit is that we can
//       load A[i][k] once per k (per row i) and reuse it across all
//       columns j, which improves cache and register reuse.
//
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	// A: i x j (n x n)
	using namespace noarr;

