		// 1) Lower triangular part: 0 <= j < i
		//    L(i, j) = (A[i][j] - sum_{k=0..j-1} A[i][k] * A[k][j]) / A[j][j]
		// -------------------------------------------------------------
		if (i_idx > 0) {
			// Restrict j to [0, i_idx)
			auto trav_j_lt_i = trav_i.order(noarr::slice<'j'>(0, i_idx));

			trav_j_lt_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				auto j_idx = get_index<'j'>(state_ij);

				// State for A[i][j]
				auto ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);

				// Use a register-local accumulator for the dot product.
				num_t sum = A[ij_state];

				if (j_idx > 0) {
					// Inner product over k = 0..j-1
					noarr::traverser(k_structure)
						.order(noarr::set_length<'k'>(j_idx))
						.for_each([&](auto k_state) {
							auto k_idx = get_index<'k'>(k_state);

							auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
							auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

							sum -= A[ik_state] * A[kj_state];
						});
				}

				// Divide by the diagonal pivot A[j][j]
				auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				sum /= A[jj_state];
				A[ij_state] = sum;
			});
		}

		// -------------------------------------------------------------
		// 2) Upper triangular part: i <= j < n
		//    U(i, j) = A[i][j] - sum_{k=0..i-1} A[i][k] * A[k][j]
		//
		//    We keep the mathematical formula but change the loop order
		//    to iterate k first, j second:
		//
		//      for k in [0, i)
		//        load aik = A[i][k]
		//        for j in [i, n)
		//          A[i][j] -= aik * A[k][j];
		//
		//    This improves reuse of A[i][k] and typically produces
		//    better vectorization and cache behavior than updating one
		//    A[i][j] at a time with a k-loop inside.
		// -------------------------------------------------------------
		auto len_second = n - i_idx;
		if (len_second > 0) {
			auto trav_j_ge_i = trav_i.order(noarr::slice<'j'>(i_idx, len_second));

			if (i_idx > 0) {
				// Outer loop over k = 0..i-1
				noarr::traverser(k_structure)
					.order(noarr::set_length<'k'>(i_idx))
					.template for_dims<'k'>([&](auto trav_k) {
						auto state_k = trav_k.state();
						auto k_idx = get_index<'k'>(state_k);

						// L(i, k) is reused for all j >= i in this row.
						auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
						const num_t aik = A[ik_state];

						// Inner loop over j = i..n-1, traversed in a cache-friendly
						// (contiguous in 'j') order thanks to the slice above.
						trav_j_ge_i.template for_dims<'j'>([&](auto trav_ij) {
							auto state_ij = trav_ij.state();
							auto j_idx = get_index<'j'>(state_ij);

							auto ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);
							auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

							A[ij_state] -= aik * A[kj_state];
						});
					});
			}
			// For i_idx == 0 there is no work (k-loop is empty), and the row
			// already holds the correct first row of U.
		}
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// A: n x n
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_lu(A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (and prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
